/**
 * Look up vendor name from MAC address (first 7 hex digits = 28-bit prefix).
 * Supports OUI (24-bit), MA-M (28-bit), and MAC-S (36-bit) assignments.
 * @param {string} mac - MAC like "80:7D:3A:78:64:AA" or "807D3A7864AA"
 * @returns {string|null} vendor name or null
 */
function ouiLookup(mac){
  var clean=mac.replace(/[^0-9A-Fa-f]/g,'').slice(0,7);
  if(clean.length<6)return null;
  while(clean.length<7)clean+='0';
  var p=parseInt(clean,16);
  var lo=0,hi=OUI_RANGES.length-1;
  while(lo<=hi){
    var mid=(lo+hi)>>1, r=OUI_RANGES[mid];
    if(r.length===2){
      if(p===r[0])return r[1];
      if(p<r[0])hi=mid-1; else lo=mid+1;
    }else{
      if(p<r[0])hi=mid-1;
      else if(p>r[1])lo=mid+1;
      else return r[2];
    }
  }
  return null;
}